from __future__ import annotations

from typing import Any, Literal, Mapping, Protocol, runtime_checkable

from pydantic import BaseModel, ConfigDict, Field


IdentityProvider = Literal["oidc", "saml"]


class AuthenticationError(PermissionError):
    """Raised when a request does not carry a valid authenticated identity context."""


class AuthorizationError(PermissionError):
    """Raised when an authenticated actor lacks a required permission."""


class AuthClaimsEnvelope(BaseModel):
    """Trusted identity claims received from an upstream auth gateway or proxy."""

    model_config = ConfigDict(frozen=True)

    provider_hint: IdentityProvider | None = None
    claims: Mapping[str, Any] = Field(default_factory=dict)


class ActorContext(BaseModel):
    """Stable, profile-independent actor context used by Slice-1 APIs."""

    model_config = ConfigDict(frozen=True)

    actor_id: str
    provider: IdentityProvider
    subject: str
    username: str
    display_name: str
    groups: tuple[str, ...] = ()
    permissions: tuple[str, ...] = ()


class MutationCommand(BaseModel):
    """Minimal authenticated write command used to prove actor propagation."""

    model_config = ConfigDict(frozen=True)

    document_id: str
    field_name: str
    value: str


class MutationResult(BaseModel):
    """Write result returned after an authorized mutation completes."""

    model_config = ConfigDict(frozen=True)

    status: str
    document_id: str
    actor_id: str
    write_result: Mapping[str, Any] = Field(default_factory=dict)


@runtime_checkable
class AuditSink(Protocol):
    """Downstream audit sink that must receive actor identity."""

    def record(
        self,
        *,
        actor: ActorContext,
        action: str,
        resource_id: str | None,
        details: Mapping[str, Any],
    ) -> None:
        ...


@runtime_checkable
class WriteSink(Protocol):
    """Downstream write sink that must receive actor identity."""

    def write(
        self,
        *,
        actor: ActorContext,
        command: MutationCommand,
    ) -> Mapping[str, Any]:
        ...
