from __future__ import annotations

import json
import logging
from typing import Any

from fastapi import APIRouter, Depends, HTTPException, Request, status

from backend.auth.contracts import (
    ActorContext,
    AuditSink,
    AuthClaimsEnvelope,
    AuthenticationError,
    AuthorizationError,
    MutationCommand,
    MutationResult,
    WriteSink,
)
from backend.auth.implementation import AuthSessionService, log_security_event

_AUTH_CLAIMS_HEADER = "x-auth-claims"
_AUTH_PROVIDER_HEADER = "x-auth-provider"
_AUTHORIZATION_HEADER = "authorization"
_SAML_ASSERTION_HEADER = "x-saml-assertion"


def _to_http_exception(exc: Exception) -> HTTPException:
    if isinstance(exc, AuthenticationError):
        return HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail=str(exc),
        )
    if isinstance(exc, AuthorizationError):
        return HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail=str(exc),
        )
    raise HTTPException(
        status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
        detail="Unexpected auth binding failure",
    )


def _extract_claims_envelope(
    *,
    request: Request,
    logger: logging.Logger | None,
) -> AuthClaimsEnvelope:
    claims_header = request.headers.get(_AUTH_CLAIMS_HEADER)
    provider_hint = request.headers.get(_AUTH_PROVIDER_HEADER)

    log_security_event(
        logger=logger,
        event="auth.request_received",
        payload={
            "provider_hint": provider_hint,
            "claims_present": bool(claims_header),
            "authorization": request.headers.get(_AUTHORIZATION_HEADER),
            "x_saml_assertion": request.headers.get(_SAML_ASSERTION_HEADER),
        },
    )

    if not claims_header:
        raise AuthenticationError("Anonymous caller is not allowed")

    try:
        claims = json.loads(claims_header)
    except json.JSONDecodeError as exc:
        raise AuthenticationError("Malformed trusted auth claims header") from exc

    if not isinstance(claims, dict):
        raise AuthenticationError("Trusted auth claims header must decode to an object")

    log_security_event(
        logger=logger,
        event="auth.claims_parsed",
        payload={
            "provider_hint": provider_hint,
            "claims": claims,
        },
    )

    return AuthClaimsEnvelope(
        provider_hint=provider_hint.lower() if provider_hint else None,
        claims=claims,
    )


def build_router(
    *,
    auth_service: AuthSessionService,
    write_sink: WriteSink,
    audit_sink: AuditSink,
    logger: logging.Logger | None = None,
) -> APIRouter:
    """
    Build repository-fit auth routes without introducing a per-REQ application bootstrap.
    """

    router = APIRouter()

    def current_actor(request: Request) -> ActorContext:
        try:
            envelope = _extract_claims_envelope(request=request, logger=logger)
            return auth_service.resolve_actor(envelope)
        except Exception as exc:  # pragma: no cover - mapped in tests via behavior
            raise _to_http_exception(exc) from exc

    def require_permission(permission: str):
        def dependency(actor: ActorContext = Depends(current_actor)) -> ActorContext:
            try:
                auth_service.ensure_permissions(actor, (permission,))
                return actor
            except Exception as exc:  # pragma: no cover - mapped in tests via behavior
                raise _to_http_exception(exc) from exc

        return dependency

    @router.get("/auth/me", response_model=ActorContext)
    def get_me(actor: ActorContext = Depends(current_actor)) -> ActorContext:
        return actor

    @router.get("/auth/protected")
    def get_protected(
        actor: ActorContext = Depends(require_permission("documents:read")),
    ) -> dict[str, Any]:
        return {
            "allowed": True,
            "actor_id": actor.actor_id,
            "permissions": list(actor.permissions),
        }

    @router.post("/auth/write", response_model=MutationResult)
    def post_write(
        command: MutationCommand,
        actor: ActorContext = Depends(current_actor),
    ) -> MutationResult:
        try:
            return auth_service.apply_mutation(
                actor=actor,
                command=command,
                required_permissions=("documents:write",),
                write_sink=write_sink,
                audit_sink=audit_sink,
            )
        except Exception as exc:  # pragma: no cover - mapped in tests via behavior
            raise _to_http_exception(exc) from exc

    return router
