from __future__ import annotations

import io
import json
import logging
import sys
from pathlib import Path

from fastapi import FastAPI
from fastapi.testclient import TestClient

REQ_ROOT = Path(__file__).resolve().parents[3]
SRC_ROOT = REQ_ROOT / "src"
if str(SRC_ROOT) not in sys.path:
    sys.path.insert(0, str(SRC_ROOT))

from backend.auth.binding import build_router
from backend.auth.contracts import ActorContext, MutationCommand
from backend.auth.implementation import AuthSessionService, PermissionPolicy


class RecordingWriteSink:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def write(
        self,
        *,
        actor: ActorContext,
        command: MutationCommand,
    ) -> dict[str, object]:
        record = {
            "actor_id": actor.actor_id,
            "username": actor.username,
            "document_id": command.document_id,
            "field_name": command.field_name,
            "value": command.value,
        }
        self.calls.append(record)
        return {
            "updated": True,
            "document_id": command.document_id,
            "field_name": command.field_name,
        }


class RecordingAuditSink:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def record(
        self,
        *,
        actor: ActorContext,
        action: str,
        resource_id: str | None,
        details: dict[str, object],
    ) -> None:
        self.calls.append(
            {
                "actor_id": actor.actor_id,
                "username": actor.username,
                "action": action,
                "resource_id": resource_id,
                "details": details,
            },
        )


def _build_client() -> tuple[TestClient, AuthSessionService, RecordingWriteSink, RecordingAuditSink, io.StringIO]:
    policy = PermissionPolicy.from_mapping(
        {
            "finance-viewers": {"documents:read"},
            "finance-editors": {"documents:read", "documents:write"},
            "auditors": {"documents:read", "audit:read"},
        },
    )

    log_stream = io.StringIO()
    logger = logging.getLogger("req002.auth")
    logger.handlers.clear()
    logger.propagate = False
    logger.setLevel(logging.INFO)
    logger.addHandler(logging.StreamHandler(log_stream))

    service = AuthSessionService(
        permission_policy=policy,
        logger=logger,
    )
    write_sink = RecordingWriteSink()
    audit_sink = RecordingAuditSink()

    app = FastAPI()
    app.include_router(
        build_router(
            auth_service=service,
            write_sink=write_sink,
            audit_sink=audit_sink,
            logger=logger,
        ),
    )

    return TestClient(app), service, write_sink, audit_sink, log_stream


def _headers(
    claims: dict[str, object] | None,
    *,
    provider: str | None = None,
    authorization: str | None = None,
    saml_assertion: str | None = None,
) -> dict[str, str]:
    headers: dict[str, str] = {}
    if claims is not None:
        headers["x-auth-claims"] = json.dumps(claims)
    if provider is not None:
        headers["x-auth-provider"] = provider
    if authorization is not None:
        headers["Authorization"] = authorization
    if saml_assertion is not None:
        headers["X-SAML-Assertion"] = saml_assertion
    return headers


def test_map_idp_claims_to_permission_set_deterministically() -> None:
    _, service, _, _, _ = _build_client()

    oidc_actor = service.resolve_actor(
        envelope=service.resolve_actor.__annotations__["return"].model_validate(  # type: ignore[index]
            {
                "actor_id": "ignore",
                "provider": "oidc",
                "subject": "ignore",
                "username": "ignore",
                "display_name": "ignore",
                "groups": (),
                "permissions": (),
            },
        ),
    ) if False else service.resolve_actor(  # noqa: E501
        __import__("backend.auth.contracts", fromlist=["AuthClaimsEnvelope"]).AuthClaimsEnvelope(
            provider_hint="oidc",
            claims={
                "sub": "user-123",
                "preferred_username": "alice",
                "name": "Alice Jones",
                "groups": ["finance-viewers", "finance-editors"],
                "scp": "audit:read documents:read",
            },
        ),
    )

    assert oidc_actor.actor_id == "oidc:user-123"
    assert oidc_actor.username == "alice"
    assert oidc_actor.display_name == "Alice Jones"
    assert oidc_actor.groups == ("finance-editors", "finance-viewers")
    assert oidc_actor.permissions == (
        "audit:read",
        "documents:read",
        "documents:write",
    )

    saml_actor = service.resolve_actor(
        __import__("backend.auth.contracts", fromlist=["AuthClaimsEnvelope"]).AuthClaimsEnvelope(
            provider_hint="saml",
            claims={
                "nameid": "saml-55",
                "http://schemas.microsoft.com/ws/2008/06/identity/claims/role": ["auditors"],
                "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name": "Bob Auditor",
            },
        ),
    )

    assert saml_actor.actor_id == "saml:saml-55"
    assert saml_actor.username == "Bob Auditor"
    assert saml_actor.display_name == "Bob Auditor"
    assert saml_actor.permissions == ("audit:read", "documents:read")


def test_get_auth_me_returns_normalized_actor_for_fixture_identity() -> None:
    client, _, _, _, _ = _build_client()

    response = client.get(
        "/auth/me",
        headers=_headers(
            {
                "sub": "fixture-user",
                "preferred_username": "fixture.alice",
                "name": "Fixture Alice",
                "groups": ["finance-editors"],
            },
            provider="oidc",
        ),
    )

    assert response.status_code == 200
    body = response.json()
    assert body["actor_id"] == "oidc:fixture-user"
    assert body["username"] == "fixture.alice"
    assert body["display_name"] == "Fixture Alice"
    assert body["permissions"] == ["documents:read", "documents:write"]


def test_protected_endpoint_returns_401_for_anonymous_and_403_for_unauthorized() -> None:
    client, _, _, _, _ = _build_client()

    anonymous = client.get("/auth/protected")
    assert anonymous.status_code == 401
    assert anonymous.json()["detail"] == "Anonymous caller is not allowed"

    unauthorized = client.get(
        "/auth/protected",
        headers=_headers(
            {
                "sub": "viewerless-user",
                "preferred_username": "viewerless",
                "groups": ["unknown-group"],
            },
            provider="oidc",
        ),
    )
    assert unauthorized.status_code == 403
    assert "documents:read" in unauthorized.json()["detail"]


def test_deny_when_required_permission_missing_with_no_business_mutation() -> None:
    client, _, write_sink, audit_sink, _ = _build_client()

    response = client.post(
        "/auth/write",
        headers=_headers(
            {
                "sub": "read-only-user",
                "preferred_username": "readonly",
                "groups": ["finance-viewers"],
            },
            provider="oidc",
        ),
        json={
            "document_id": "doc-001",
            "field_name": "invoice_number",
            "value": "INV-100",
        },
    )

    assert response.status_code == 403
    assert "documents:write" in response.json()["detail"]
    assert write_sink.calls == []
    assert audit_sink.calls == []


def test_propagates_actor_identity_into_downstream_audit_and_write_paths() -> None:
    client, _, write_sink, audit_sink, _ = _build_client()

    response = client.post(
        "/auth/write",
