from typing import Any, Literal, Mapping, Protocol, runtime_checkable

from pydantic import BaseModel, ConfigDict, Field


IdentityProvider = Literal["oidc", "saml"]


class AuthenticationError(PermissionError):
    """Raised when a request does not carry a valid authenticated identity context."""


class AuthorizationError(PermissionError):
    """Raised when an authenticated actor lacks a required permission."""


class AuthClaimsEnvelope(BaseModel):
    """Trusted identity claims received from an upstream auth gateway or proxy."""

    model_config = ConfigDict(frozen=True)

    provider_hint: IdentityProvider | None = None
    claims: Mapping[str, Any] = Field(default_factory=dict)


class ActorContext(BaseModel):
    """Stable, profile-independent actor context used by Slice-1 APIs."""

    model_config = ConfigDict(frozen=True)

    actor_id: str
    provider: IdentityProvider
    subject: str
    username: str
    display_name: str
    groups: tuple[str, ...] = ()
    permissions: tuple[str, ...] = ()


