from __future__ import annotations

import logging
from dataclasses import dataclass
from typing import Any, Iterable, Mapping, Sequence

from backend.auth.contracts import (
    ActorContext,
    AuditSink,
    AuthClaimsEnvelope,
    AuthenticationError,
    AuthorizationError,
    MutationCommand,
    MutationResult,
    WriteSink,
)

LOGGER = logging.getLogger(__name__)

_OIDC_SUBJECT_KEYS: tuple[str, ...] = ("sub",)
_SAML_SUBJECT_KEYS: tuple[str, ...] = (
    "nameid",
    "name_id",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier",
)

_USERNAME_KEYS: tuple[str, ...] = (
    "preferred_username",
    "username",
    "email",
    "upn",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name",
)

_DISPLAY_NAME_KEYS: tuple[str, ...] = (
    "name",
    "display_name",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name",
)

_GROUP_KEYS: tuple[str, ...] = (
    "groups",
    "roles",
    "http://schemas.microsoft.com/ws/2008/06/identity/claims/role",
    "http://schemas.xmlsoap.org/claims/Group",
)

_DIRECT_PERMISSION_KEYS: tuple[str, ...] = (
    "permissions",
    "scp",
    "scope",
    "entitlements",
    "urn:example:permissions",
)

_SENSITIVE_KEY_FRAGMENTS: tuple[str, ...] = (
    "authorization",
    "token",
    "assertion",
    "credential",
    "secret",
    "password",
    "samlresponse",
    "id_token",
    "access_token",
    "refresh_token",
)

_REDACTED = "[REDACTED]"


def redact_sensitive_data(value: Any) -> Any:
    """Recursively redact token-like and assertion-like fields before logging."""

    if isinstance(value, Mapping):
        redacted: dict[str, Any] = {}
        for key, item in value.items():
            normalized_key = str(key).lower().replace("-", "").replace("_", "")
            if any(fragment in normalized_key for fragment in _SENSITIVE_KEY_FRAGMENTS):
                redacted[str(key)] = _REDACTED
            else:
                redacted[str(key)] = redact_sensitive_data(item)
        return redacted

    if isinstance(value, tuple):
        return tuple(redact_sensitive_data(item) for item in value)

    if isinstance(value, list):
        return [redact_sensitive_data(item) for item in value]

    if isinstance(value, set):
        return {redact_sensitive_data(item) for item in value}

    return value


def log_security_event(
    *,
    logger: logging.Logger | None,
    event: str,
    payload: Mapping[str, Any],
) -> None:
    """Emit auth-related logs only after redacting sensitive material."""

    active_logger = logger or LOGGER
    active_logger.info("%s %s", event, redact_sensitive_data(payload))


def _normalize_identifier(value: str) -> str:
    normalized = value.strip()
    if not normalized:
        raise AuthenticationError("Authenticated claim value resolved to empty identifier")
    return normalized


def _coerce_string_values(value: Any, *, split_whitespace: bool) -> tuple[str, ...]:
    if value is None:
        return ()

    if isinstance(value, str):
        raw_items = [value]
    elif isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray, str)):
        raw_items = [str(item) for item in value if item is not None]
    else:
        raw_items = [str(value)]

    parts: list[str] = []
    for item in raw_items:
        candidates = [item]
        if split_whitespace:
            candidates = item.replace(",", " ").replace(";", " ").split()
        else:
            delimiter_normalized = item.replace(";", ",")
            candidates = delimiter_normalized.split(",")

        for candidate in candidates:
            stripped = candidate.strip()
            if stripped:
                parts.append(stripped)

    return tuple(parts)


def _first_string(claims: Mapping[str, Any], keys: Sequence[str]) -> str | None:
    for key in keys:
        if key not in claims:
            continue
        value = claims[key]
        if value is None:
            continue
        if isinstance(value, str):
            stripped = value.strip()
            if stripped:
                return stripped
            continue
        if isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray, str)):
            for item in value:
                if item is None:
                    continue
                stripped = str(item).strip()
                if stripped:
                    return stripped
    return None


def _provider_from_claims(
    *,
    claims: Mapping[str, Any],
    provider_hint: str | None,
) -> str:
    if provider_hint:
        normalized_hint = provider_hint.strip().lower()
        if normalized_hint in {"oidc", "saml"}:
            return normalized_hint

    if _first_string(claims, _OIDC_SUBJECT_KEYS):
        return "oidc"

    if _first_string(claims, _SAML_SUBJECT_KEYS):
        return "saml"

    if any(key in claims for key in ("preferred_username", "email", "scp", "scope")):
        return "oidc"

    if any(key in claims for key in _SAML_SUBJECT_KEYS[1:]):
        return "saml"

    raise AuthenticationError("Unable to determine identity provider from trusted claims")


@dataclass(frozen=True)
class PermissionPolicy:
    """Deterministic group-to-permission mapping independent of deployment profile."""

    group_permissions: Mapping[str, frozenset[str]]
    direct_permission_claim_names: tuple[str, ...] = _DIRECT_PERMISSION_KEYS

    @classmethod
    def from_mapping(
        cls,
        group_permissions: Mapping[str, Iterable[str]],
        *,
        direct_permission_claim_names: Sequence[str] = _DIRECT_PERMISSION_KEYS,
    ) -> "PermissionPolicy":
        normalized_mapping: dict[str, frozenset[str]] = {}
        for group_ref, permissions in group_permissions.items():
            group_key = group_ref.strip().lower()
            normalized_permissions = frozenset(
                permission.strip().lower()
                for permission in permissions
                if str(permission).strip()
            )
            normalized_mapping[group_key] = normalized_permissions
        return cls(
            group_permissions=normalized_mapping,
            direct_permission_claim_names=tuple(direct_permission_claim_names),
        )

    def permissions_for_groups(self, groups: Iterable[str]) -> frozenset[str]:
        permissions: set[str] = set()
        for group in groups:
            permissions.update(self.group_permissions.get(group.strip().lower(), frozenset()))
        return frozenset(permissions)


class AuthSessionService:
    """Owns claim normalization, permission evaluation, and actor-aware mutation orchestration."""

    def __init__(
        self,
        *,
        permission_policy: PermissionPolicy,
        logger: logging.Logger | None = None,
    ) -> None:
        self._permission_policy = permission_policy
        self._logger = logger

    def resolve_actor(self, envelope: AuthClaimsEnvelope) -> ActorContext:
        claims = dict(envelope.claims)
        provider = _provider_from_claims(
            claims=claims,
            provider_hint=envelope.provider_hint,
        )
        subject = _first_string(
            claims,
            _OIDC_SUBJECT_KEYS if provider == "oidc" else _SAML_SUBJECT_KEYS,
        )
        if not subject:
            raise AuthenticationError("Authenticated identity is missing a stable subject claim")

        normalized_subject = _normalize_identifier(subject)
        groups = self._extract_groups(claims)
        permissions = self._extract_permissions(claims, groups)
        username = self._extract_username(claims, normalized_subject)
        display_name = self._extract_display_name(claims, username)

        actor = ActorContext(
            actor_id=f"{provider}:{normalized_subject}",
            provider=provider,
            subject=normalized_subject,
            username=username,
            display_name=display_name,
            groups=tuple(sorted(groups)),
            permissions=tuple(sorted(permissions)),
        )

        log_security_event(
            logger=self._logger,
            event="auth.actor_resolved",
            payload={
                "provider": actor.provider,
                "actor_id": actor.actor_id,
                "username": actor.username,
                "groups": actor.groups,
                "permissions": actor.permissions,
                "claims": claims,
            },
        )
        return actor

    def ensure_permissions(
        self,
        actor: ActorContext,
        required_permissions: Iterable[str],
    ) -> None:
        required = {
            permission.strip().lower()
            for permission in required_permissions
            if permission and permission.strip()
        }
        if not required:
            return

        actor_permissions = {permission.lower() for permission in actor.permissions}
        missing = sorted(required - actor_permissions)
        if missing:
            raise AuthorizationError(
                f"Authenticated actor lacks required permissions: {', '.join(missing)}",
            )

    def apply_mutation(
        self,
        *,
        actor: ActorContext,
        command: MutationCommand,
        required_permissions: Iterable[str],
        write_sink: WriteSink,
        audit_sink: AuditSink,
    ) -> MutationResult:
        self.ensure_permissions(actor, required_permissions)

        write_result = write_sink.write(actor=actor, command=command)

        audit_sink.record(
            actor=actor,
            action="documents.write",
            resource_id=command.document_id,
            details={
                "field_name": command.field_name,
                "document_id": command.document_id,
            },
        )

        log_security_event(
            logger=self._logger,
            event="auth.mutation_applied",
            payload={
                "actor_id": actor.actor_id,
                "document_id": command.document_id,
                "field_name": command.field_name,
                "write_result": write_result,
            },
        )

        return MutationResult(
            status="applied",
            document_id=command.document_id,
            actor_id=actor.actor_id,
            write_result=write_result,
        )

    def _extract_username(
        self,
        claims: Mapping[str, Any],
        subject: str,
    ) -> str:
        username = _first_string(claims, _USERNAME_KEYS)
        return _normalize_identifier(username or subject)

    def _extract_display_name(
        self,
        claims: Mapping[str, Any],
        username: str,
    ) -> str:
        display_name = _first_string(claims, _DISPLAY_NAME_KEYS)
        return _normalize_identifier(display_name or username)

    def _extract_groups(self, claims: Mapping[str, Any]) -> frozenset[str]:
        groups: set[str] = set()
        for key in _GROUP_KEYS:
            if key not in claims:
                continue
            for item in _coerce_string_values(claims[key], split_whitespace=False):
                groups.add(item.strip().lower())
        return frozenset(groups)

    def _extract_permissions(
        self,
        claims: Mapping[str, Any],
        groups: frozenset[str],
    ) -> frozenset[str]:
        permissions: set[str] = set(self._permission_policy.permissions_for_groups(groups))
        for key in self._permission_policy.direct_permission_claim_names:
            if key not in claims:
                continue
            split_whitespace = key in {"scp", "scope"}
            for item in _coerce_string_values(claims[key], split_whitespace=split_whitespace):
                permissions.add(item.strip().lower())
        return frozenset(permissions)
